/**
 * Hides the filter text (e.g., "Showing 9 of 15 satellites (show all)") and resets the
 * number of satellites view back to a normal (non-italic) typeface
 */
private void hideFilterView() {
    if (filterGroup != null) {
        filterGroup.setVisibility(View.GONE);
    }
    if (filterTextView != null) {
        filterTextView.setText("");
    }
    if (mNumSats != null) {
        // Set num sats view back to normal
        mNumSats.setTypeface(null, Typeface.NORMAL);
    }
}

